  $('patient-name').innerHTML=`${p.name} <span class="tag">Demo patient</span>`;$('patient-meta').textContent=`${p.age} years · Asthma tracker · Enrolled May 2026`;$('crumb').textContent=p.name;$('initials').textContent=p.name.split(' ').map(x=>x[0]).join('');$('date-label').textContent=`${fmt(r[0].date)} – ${fmt(r.at(-1).date)}, 2026 · ${r.length} days`;
  const now=oneMinuteStats(r,p.personalBest);
