  $('symptoms').querySelectorAll('.symptom-detail-toggle').forEach(button=>{button.onclick=()=>{const panel=$(button.getAttribute('aria-controls'));const open=button.getAttribute('aria-expanded')!=='true';button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',`${open?'Hide':'Show'} dates and combinations for ${button.parentElement.querySelector('span').textContent}`);panel.classList.toggle('hidden',!open);};});
const specialty=$('specialty').value;const prompts=specialty==='Nursing'?['Explore whether reminders and dose logging fit the daily routine.','Review missing entries and spirometry technique with the family.','Confirm the current medication schedule and action plan.']:specialty==='Primary care'?['Ask how symptoms are affecting school and everyday activities.','Discuss barriers to reporting or taking scheduled medication.','Review changes with the patient and their specialty care team.']:['Review symptom days alongside accepted lung-function readings.','Explore whether unreported doses reflect missed treatment or logging gaps.','Check device technique and clarify conflicting quality reports.'];$('prompts').innerHTML=prompts.map((s,i)=>`<div class="prompt"><span>0${i+1}</span><div>${s}</div></div>`).join('');
$('timeline').style.gridTemplateColumns=`repeat(${r.length},minmax(18px,1fr))`;$('timeline').innerHTML=r.map(d=>`<button class="day ${d.zone}" data-date="${d.date}" aria-label="${fmt(d.date)}: ${d.zone==='unknown'?'no entry':d.zone+' zone'}. Review day"><i></i>${+d.date.slice(-2)}</button>`).join('');
const excluded=allReadings.length-accepted.length;
  $('quality-title').textContent=`Data coverage & interpretation · ${r.length-logged.length} days without entries · ${excluded} FEV1 readings excluded from trend`;
  $('quality-content').innerHTML=`<p><strong>Daily aggregation:</strong> repeated tracker submissions count as one tracked day. Symptoms use the union of answers; wellbeing uses the latest answer; zone uses the most concerning recorded status. Every spirometry reading is plotted. The line uses each day's best accepted FEV1. It connects available days across gaps and does not imply measurements on missing days.</p><p><strong>Quality:</strong> ${excluded} rejected or conflicting readings appear as hollow markers but do not enter the daily best trend. No quality flag is silently resolved. Values are shown to two decimal places with units.</p><p><strong>Medication:</strong> ${doses}/${expected} scheduled doses were reported. The denominator assumes an unchanged twice-daily schedule throughout this fictional period. Missing reports do not establish missed doses. Rescue medication is not included in this percentage.</p><p><strong>Scope:</strong> All records are generated examples, anchored to June 24, 2026. The summary is computed from displayed records, not AI clinical advice. No live monitoring or medical-record integration.</p>`;
